  readonly completedOn: string;
}

export interface CasePanel {
  readonly heading: string;
  readonly bannerUrl: string;
  readonly paragraphs: readonly string[];
  readonly attachments: readonly string[];
  readonly customer: string;
  readonly categoryLink: { readonly label: string; readonly href: "#"; readonly preventsNavigation: true };
  readonly completedOn: string;
}

export function buildCasePanel(data: CaseData, visible: boolean): CasePanel | null {
  if (!visible) return null;
  const values = [data.title, data.bannerUrl, data.customer, data.category, data.completedOn, ...data.paragraphs, ...data.attachments];
  if (values.some((value) => value.trim() === "")) {
    throw new RangeError("case fields must not be empty");
  }
  return {
    heading: data.title,
    bannerUrl: data.bannerUrl,
    paragraphs: [...data.paragraphs],
    attachments: data.attachments,
    customer: data.customer,
    categoryLink: { label: data.category, href: "#", preventsNavigation: true },
    completedOn: data.completedOn
  };
}

