import { buildCasePanel } from './solution';
import type { CaseData } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsRange(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

const paragraphs = [' first paragraph ', 'second'];
const attachments = ['https://example.test/a', ' file.pdf '];
const data: CaseData = {
  title: ' A case ',
  bannerUrl: 'banner.png',
  customer: 'Customer',
  category: 'Retail',
  completedOn: '2026-08-29',
  paragraphs,
  attachments
};
const panel = buildCasePanel(data, true);
assert(panel !== null, 'visible data creates a panel');
if (panel === null) throw new Error('unreachable');
equal(panel.heading, data.title, 'title becomes heading unchanged');
equal(panel.bannerUrl, data.bannerUrl, 'banner URL preserved');
equal(panel.customer, data.customer, 'customer preserved');
equal(panel.completedOn, data.completedOn, 'completion value preserved');
equal(panel.categoryLink.label, data.category, 'category label preserved');
equal(panel.categoryLink.href, '#', 'category href');
equal(panel.categoryLink.preventsNavigation, true, 'category prevents navigation');
assert(panel.paragraphs !== paragraphs, 'paragraph array is copied');
assert(panel.attachments !== attachments, 'attachment array is copied');
assert(panel.paragraphs[0] === ' first paragraph ' && panel.paragraphs[1] === 'second', 'paragraph order and values preserved');
assert(panel.attachments[0] === 'https://example.test/a' && panel.attachments[1] === ' file.pdf ', 'attachment order and values preserved');
paragraphs[0] = 'mutated';
attachments.push('later');
equal(panel.paragraphs[0], ' first paragraph ', 'paragraph result does not alias caller array');
equal(panel.attachments.length, 2, 'attachment result does not alias caller array');

const emptyLists = buildCasePanel({ ...data, paragraphs: [], attachments: [] }, true);
assert(emptyLists !== null && emptyLists.paragraphs.length === 0 && emptyLists.attachments.length === 0, 'empty collections are valid');

equal(buildCasePanel({ ...data, title: ' ' }, false), null, 'hidden data returns null without requiring visible content');
const scalarKeys: Array<keyof Pick<CaseData, 'title' | 'bannerUrl' | 'customer' | 'category' | 'completedOn'>> = ['title', 'bannerUrl', 'customer', 'category', 'completedOn'];
for (const key of scalarKeys) {
  throwsRange(() => buildCasePanel({ ...data, [key]: '\t ' }, true), `${key} must be non-empty`);
}
throwsRange(() => buildCasePanel({ ...data, paragraphs: ['ok', ' '] }, true), 'empty paragraph rejected');
throwsRange(() => buildCasePanel({ ...data, attachments: ['\n'] }, true), 'empty attachment rejected');

